statement:
Напишите **async**-функцию `loadJson(url)`, которая **никогда не бросает ошибку**, а возвращает объект:

- `{ ok: true, data }` — если ответ успешен и тело — корректный JSON;
- `{ ok: false, error: "HTTP 404" }` — если ответ пришёл, но не ok (подставьте реальный статус);
- `{ ok: false, error: "network" }` — если запрос не удался (обещание отклонено);
- `{ ok: false, error: "bad json" }` — если тело не разбирается как JSON.

starterCode:
const users = {
  1: { id: 1, name: "Аня", age: 30 },
  2: { id: 2, name: "Борис", age: 25 },
  3: { id: 3, name: "Вера", age: 41 },
};

async function fakeFetch(url) {
  if (url === "/offline") throw new TypeError("Failed to fetch");
  if (url === "/broken") return new Response("<html>oops", { status: 200 });
  if (url === "/users") return new Response(JSON.stringify(Object.values(users)), { status: 200 });
  const m = /^\/users\/(\d+)$/.exec(url);
  if (m && users[m[1]]) return new Response(JSON.stringify(users[m[1]]), { status: 200 });
  return new Response(JSON.stringify({ error: "not found" }), { status: 404 });
}

async function loadJson(url) {
